1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// setupContendingRound 建立竞争候选场景：本地提议含 Alice（费用 20）与
9	// Bob（费用 10）两笔不同账户的交易，竞争候选只含 Alice 交易；四名验证者中
10	// keys[0] 投本地提议、keys[1] 投竞争候选，keys[2]、keys[3] 尚未投票。
11	// 返回节点、本地提议、竞争候选标识与两笔交易标识。
12	func setupContendingRound(t *testing.T) (n *Node, keys []testKey, local ProposalView, altID, aliceID, bobID string) {
13		t.Helper()
14		keys = genKeys(t, 4)
15		n, _ = newTestNode(t, keys, 10)
16		alice := NewTransaction(keys[0].priv, 1, []byte("alice"), 20, 100)
17		bob := NewTransaction(keys[1].priv, 1, []byte("bob"), 10, 100)
18		if _, err := n.Submit(alice); err != nil {
19			t.Fatal(err)
20		}
21		if _, err := n.Submit(bob); err != nil {
22			t.Fatal(err)
23		}
24		aliceID, bobID = alice.ID(), bob.ID()
25	
26		var err error
27		local, err = n.Propose()
28		if err != nil {
29			t.Fatal(err)
30		}
31		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{aliceID, bobID}) {
32			t.Fatalf("setup: local proposal = %v, want [%s %s]", local.TxIDs, aliceID, bobID)
33		}
34		altID = registerMust(t, n, 1, []string{aliceID})
35		if altID == local.BlockID {
36			t.Fatal("setup: contending candidate must differ from local proposal")
37		}
38		if res, err := n.Vote(keys[0].pub, 1, local.BlockID); err != nil || !res.Counted {
39			t.Fatalf("setup: vote for local: %+v %v", res, err)
40		}
41		if res, err := n.Vote(keys[1].pub, 1, altID); err != nil || !res.Counted {
42			t.Fatalf("setup: vote for alt: %+v %v", res, err)
43		}
44		return n, keys, local, altID, aliceID, bobID
45	}
46	
47	// pubHexList 返回公钥列表的十六进制形式，便于与期望值比较。
48	func pubHexList(pubs [][]byte) []string {
49		out := make([]string, len(pubs))
50		for i, p := range pubs {
51			out[i] = fmt.Sprintf("%x", p)
52		}
53		return out
54	}
55	
56	// sortedPubHex 返回按十六进制定序的公钥列表（节点返回投票者与未投票名单的顺序）。
57	func sortedPubHex(pubs ...[]byte) []string {
58		out := pubHexList(pubs)
59		sortStrings(out)
60		return out
61	}
62	
63	// candidateByID 在轮次查询结果中按区块标识找到候选视图，找不到则失败。
64	func candidateByID(t *testing.T, rc *RoundCandidates, blockID string) *CandidateView {
65		t.Helper()
66		for i := range rc.Candidates {
67			if rc.Candidates[i].BlockID == blockID {
68				return &rc.Candidates[i]
69			}
70		}
71		t.Fatalf("candidate %s missing from %+v", blockID, rc.Candidates)
72		return nil
73	}
74	
75	// assertPendingContendingView 校验轮次查询结果正是投票后、决出前的真实记录：
76	// 两个候选按区块标识排序且均为 pending，各自保留真实交易顺序与投票者，
77	// keys[2]、keys[3] 按公钥序列入未投票名单，轮次未结束。
78	func assertPendingContendingView(t *testing.T, rc *RoundCandidates, keys []testKey, localID, altID, aliceID, bobID string) {
79		t.Helper()
80		if rc.Round != 1 || rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
81			t.Fatalf("round view header wrong: %+v", rc)
82		}
83		if len(rc.Candidates) != 2 {
84			t.Fatalf("candidates = %d, want 2: %+v", len(rc.Candidates), rc.Candidates)
85		}
86		if rc.Candidates[0].BlockID > rc.Candidates[1].BlockID {
87			t.Fatalf("candidates not sorted by block id: %s then %s",
88				rc.Candidates[0].BlockID, rc.Candidates[1].BlockID)
89		}
90		local := candidateByID(t, rc, localID)
91		if !local.Local || local.Result != CandidatePending || local.Round != 1 {
92			t.Fatalf("local candidate wrong: %+v", local)
93		}
94		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{aliceID, bobID}) {
95			t.Fatalf("local tx order = %v, want [%s %s]", local.TxIDs, aliceID, bobID)
96		}
97		if fmt.Sprint(pubHexList(local.Voters)) != fmt.Sprint(sortedPubHex(keys[0].pub)) {
98			t.Fatalf("local voters = %x, want keys[0]", local.Voters)
99		}
100		alt := candidateByID(t, rc, altID)
101		if alt.Local || alt.Result != CandidatePending || alt.Round != 1 {
102			t.Fatalf("alt candidate wrong: %+v", alt)
103		}
104		if fmt.Sprint(alt.TxIDs) != fmt.Sprint([]string{aliceID}) {
105			t.Fatalf("alt tx order = %v, want [%s]", alt.TxIDs, aliceID)
106		}
107		if fmt.Sprint(pubHexList(alt.Voters)) != fmt.Sprint(sortedPubHex(keys[1].pub)) {
108			t.Fatalf("alt voters = %x, want keys[1]", alt.Voters)
109		}
110		if fmt.Sprint(pubHexList(rc.Unvoted)) != fmt.Sprint(sortedPubHex(keys[2].pub, keys[3].pub)) {
111			t.Fatalf("unvoted = %x, want keys[2] and keys[3] sorted", rc.Unvoted)
112		}
113	}
114	
115	// 同一轮存在本地提议与竞争候选、两者共享 Alice 交易且各有一票时，连续取得的
116	// 两份查询结果彼此独立：改写其中一份的候选标识、结果、交易列表、投票者公钥字节
117	// 与未投票名单，另一份保持取得时的内容，再次查询仍看到节点的真实记录；同一份
118	// 结果内共享交易的两个候选也各有独立的交易列表。本轮未结束时，编辑查询结果
119	// 不能伪造投票：重复投原候选不增票，改投被拒绝且原选择保留。
120	func TestCandidatesQueryResultsAreIndependentCopies(t *testing.T) {
121		n, keys, local, altID, aliceID, bobID := setupContendingRound(t)
122		localID := local.BlockID
123	
124		// 连续取得两份结果。
125		first, err := n.Candidates(1)
126		if err != nil {
127			t.Fatal(err)
128		}
129		second, err := n.Candidates(1)
130		if err != nil {
131			t.Fatal(err)
132		}
133		assertPendingContendingView(t, first, keys, localID, altID, aliceID, bobID)
134	
135		// 调用方尽力改写第一份结果：轮次头、候选标识、结果、交易列表、
136		// 投票者公钥字节与名单、未投票名单。
137		first.Round = 99
138		first.Ended = true
139		first.UnconfirmedEnd = true
140		firstLocal := candidateByID(t, first, localID)
141		firstLocal.BlockID = "tampered-local-id"
142		firstLocal.Result = CandidateWon
143		firstLocal.TxIDs[0] = "tampered-tx"
144		firstLocal.TxIDs = append(firstLocal.TxIDs, "forged-extra-tx")
145		firstLocal.Voters[0][0] ^= 0xff
146		firstLocal.Voters = append(firstLocal.Voters, keys[2].pub)
147		firstAlt := candidateByID(t, first, altID)
148		firstAlt.Result = CandidateLost
149		firstAlt.TxIDs = nil
150		first.Unvoted[0][0] ^= 0xff
151		first.Unvoted = append(first.Unvoted, keys[0].pub)
152	
153		// 第二份结果保持取得时的内容。
154		assertPendingContendingView(t, second, keys, localID, altID, aliceID, bobID)
155	
156		// 再次查询仍看到节点的真实记录。
157		third, err := n.Candidates(1)
158		if err != nil {
159			t.Fatal(err)
160		}
161		assertPendingContendingView(t, third, keys, localID, altID, aliceID, bobID)
162	
163		// 同一份结果内，共享 Alice 交易的两个候选各有独立列表：
164		// 改写本地候选的交易列表，竞争候选的列表不变，反之亦然。
165		secondLocal := candidateByID(t, second, localID)
166		secondAlt := candidateByID(t, second, altID)
167		secondLocal.TxIDs[0] = "tampered-shared-tx"
168		if secondAlt.TxIDs[0] != aliceID {
169			t.Fatalf("editing local tx list changed alt list: %v", secondAlt.TxIDs)
170		}
171		secondAlt.TxIDs[0] = "tampered-alt-tx"
172		if secondLocal.TxIDs[1] != bobID {
173			t.Fatalf("editing alt tx list changed local list: %v", secondLocal.TxIDs)
174		}
175	
176		// 编辑查询结果不能伪造投票：真实验证者重复投原候选不增票。
177		if res, err := n.Vote(keys[1].pub, 1, altID); err != nil || res.Counted {
178			t.Fatalf("duplicate vote after result tamper: %+v %v", res, err)
179		}
180		if res, err := n.Vote(keys[0].pub, 1, localID); err != nil || res.Counted {
181			t.Fatalf("duplicate local vote after result tamper: %+v %v", res, err)
182		}
183		// 改投仍被拒绝，原选择保留。
184		if _, err := n.Vote(keys[1].pub, 1, localID); reason(err) != ReasonAlreadyVoted {
185			t.Fatalf("switch vote after result tamper got %v, want %s", err, ReasonAlreadyVoted)
186		}
187		if _, err := n.Vote(keys[0].pub, 1, altID); reason(err) != ReasonAlreadyVoted {
188			t.Fatalf("switch local vote after result tamper got %v, want %s", err, ReasonAlreadyVoted)
189		}
190		after, err := n.Candidates(1)
191		if err != nil {
192			t.Fatal(err)
193		}
194		assertPendingContendingView(t, after, keys, localID, altID, aliceID, bobID)
195	}
196	
197	// 查询结果是取得时的快照：保留未编辑的旧结果后，剩余两名验证者继续投给竞争
198	// 候选，第二票仍不能确认（严格超过 2/3 才确认，四人名单需 3 票），第三票立即
199	// 确认并进入下一轮。新查询旧轮次显示竞争候选胜出、本地提议落选、各候选保留
200	// 实际投票者、未投票名单为空；先前保留的结果仍显示当时双方各一票、两个候选
201	// 未决、两人未投票，不随节点变化而更新。
202	func TestCandidatesQuerySnapshotSurvivesConfirmation(t *testing.T) {
203		n, keys, local, altID, aliceID, bobID := setupContendingRound(t)
204		localID := local.BlockID
205	
206		// 保留一份未编辑的旧结果。
207		saved, err := n.Candidates(1)
208		if err != nil {
209			t.Fatal(err)
210		}
211		assertPendingContendingView(t, saved, keys, localID, altID, aliceID, bobID)
212	
213		// 第二票投给竞争候选：计入但仍未确认（2 票未严格超过 4 人的 2/3）。
214		res, err := n.Vote(keys[2].pub, 1, altID)
215		if err != nil || !res.Counted || res.Confirmed {
216			t.Fatalf("second alt vote: %+v %v", res, err)
217		}
218		if n.CurrentRound() != 1 {
219			t.Fatalf("round advanced at 2 votes: %d", n.CurrentRound())
220		}
221		// 第三票立即确认并进入下一轮。
222		res, err = n.Vote(keys[3].pub, 1, altID)
223		if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
224			t.Fatalf("third alt vote should confirm: %+v %v", res, err)
225		}
226		if n.CurrentRound() != 2 || n.Height() != 1 {
227			t.Fatalf("after confirm round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
228		}
229	
230		// 新查询旧轮次：竞争候选胜出、本地提议落选，各候选保留实际投票者，
231		// 未投票名单为空。
232		decided, err := n.Candidates(1)
233		if err != nil {
234			t.Fatal(err)
235		}
236		if !decided.Ended || decided.UnconfirmedEnd || len(decided.Unvoted) != 0 {
237			t.Fatalf("decided round view wrong: %+v", decided)
238		}
239		if len(decided.Candidates) != 2 ||
240			decided.Candidates[0].BlockID > decided.Candidates[1].BlockID {
241			t.Fatalf("decided candidates wrong: %+v", decided.Candidates)
242		}
243		won := candidateByID(t, decided, altID)
244		if won.Result != CandidateWon || won.Local {
245			t.Fatalf("alt candidate should have won: %+v", won)
246		}
247		if fmt.Sprint(won.TxIDs) != fmt.Sprint([]string{aliceID}) {
248			t.Fatalf("won tx order = %v, want [%s]", won.TxIDs, aliceID)
249		}
250		if fmt.Sprint(pubHexList(won.Voters)) != fmt.Sprint(sortedPubHex(keys[1].pub, keys[2].pub, keys[3].pub)) {
251			t.Fatalf("won voters = %x, want keys[1..3] sorted", won.Voters)
252		}
253		lost := candidateByID(t, decided, localID)
254		if lost.Result != CandidateLost || !lost.Local {
255			t.Fatalf("local candidate should have lost: %+v", lost)
256		}
257		if fmt.Sprint(lost.TxIDs) != fmt.Sprint([]string{aliceID, bobID}) {
258			t.Fatalf("lost tx order = %v, want [%s %s]", lost.TxIDs, aliceID, bobID)
259		}
260		if fmt.Sprint(pubHexList(lost.Voters)) != fmt.Sprint(sortedPubHex(keys[0].pub)) {
261			t.Fatalf("lost voters = %x, want keys[0]", lost.Voters)
262		}
263	
264		// 先前保留的结果仍显示取得时的内容：双方各一票、两个候选未决、两人未投票。
265		assertPendingContendingView(t, saved, keys, localID, altID, aliceID, bobID)
266	}
267	
268	// 空交易列表的候选与尚无投票的候选遵守相同的独立副本约定：调用方在返回结果中
269	// 自行添加交易或投票者，不会在节点中登记出新内容；候选按区块标识排序、公钥按
270	// 字典序排列的返回行为保持不变。
271	func TestCandidatesQueryEmptyAndVotelessCandidateCopy(t *testing.T) {
272		keys := genKeys(t, 4)
273		n, _ := newTestNode(t, keys, 10)
274		alice := NewTransaction(keys[0].priv, 1, []byte("alice"), 5, 100)
275		if _, err := n.Submit(alice); err != nil {
276			t.Fatal(err)
277		}
278		local, err := n.Propose()
279		if err != nil {
280			t.Fatal(err)
281		}
282		emptyID := registerMust(t, n, 1, nil) // 空交易列表的竞争候选
283		if emptyID != BlockID(1, 1, "", []string{}) {
284			t.Fatalf("empty candidate id = %s, want recomputed %s", emptyID, BlockID(1, 1, "", []string{}))
285		}
286		// 只有本地提议得到一票；空候选既无交易也无投票。
287		if res, err := n.Vote(keys[0].pub, 1, local.BlockID); err != nil || !res.Counted {
288			t.Fatalf("setup: vote for local: %+v %v", res, err)
289		}
290	
291		rc, err := n.Candidates(1)
292		if err != nil {
293			t.Fatal(err)
294		}
295		if len(rc.Candidates) != 2 || rc.Candidates[0].BlockID > rc.Candidates[1].BlockID {
296			t.Fatalf("candidates not sorted by block id: %+v", rc.Candidates)
297		}
298		empty := candidateByID(t, rc, emptyID)
299		if len(empty.TxIDs) != 0 || len(empty.Voters) != 0 || empty.Result != CandidatePending {
300			t.Fatalf("setup: empty candidate wrong: %+v", empty)
301		}
302		if fmt.Sprint(pubHexList(rc.Unvoted)) != fmt.Sprint(sortedPubHex(keys[1].pub, keys[2].pub, keys[3].pub)) {
303			t.Fatalf("setup: unvoted = %x, want keys[1..3] sorted", rc.Unvoted)
304		}
305	
306		// 调用方在手中的结果里为空候选添加交易与投票者，并改写本地候选的列表。
307		empty.TxIDs = append(empty.TxIDs, alice.ID(), "forged-tx")
308		empty.Voters = append(empty.Voters, keys[1].pub)
309		empty.Result = CandidateWon
310		localView := candidateByID(t, rc, local.BlockID)
311		localView.TxIDs[0] = "tampered-tx"
312		localView.Voters[0][0] ^= 0xff
313		rc.Unvoted[0][0] ^= 0xff
314	
315		// 再次查询：空候选仍无交易、无投票者，本地候选保持真实记录。
316		again, err := n.Candidates(1)
317		if err != nil {
318			t.Fatal(err)
319		}
320		if len(again.Candidates) != 2 {
321			t.Fatalf("caller edits registered new candidates: %+v", again.Candidates)
322		}
323		emptyAgain := candidateByID(t, again, emptyID)
324		if len(emptyAgain.TxIDs) != 0 || len(emptyAgain.Voters) != 0 || emptyAgain.Result != CandidatePending {
325			t.Fatalf("caller edits leaked into empty candidate: %+v", emptyAgain)
326		}
327		localAgain := candidateByID(t, again, local.BlockID)
328		if fmt.Sprint(localAgain.TxIDs) != fmt.Sprint([]string{alice.ID()}) {
329			t.Fatalf("local tx list changed by caller edit: %v", localAgain.TxIDs)
330		}
331		if fmt.Sprint(pubHexList(localAgain.Voters)) != fmt.Sprint(sortedPubHex(keys[0].pub)) {
332			t.Fatalf("local voters changed by caller edit: %x", localAgain.Voters)
333		}
334		if fmt.Sprint(pubHexList(again.Unvoted)) != fmt.Sprint(sortedPubHex(keys[1].pub, keys[2].pub, keys[3].pub)) {
335			t.Fatalf("unvoted changed by caller edit: %x", again.Unvoted)
336		}
337	
338		// 节点没有登记出伪造的投票：keys[1] 投给空候选仍是第一票、正常计入。
339		res, err := n.Vote(keys[1].pub, 1, emptyID)
340		if err != nil || !res.Counted || res.Confirmed {
341			t.Fatalf("first real vote for empty candidate: %+v %v", res, err)
342		}
343		final, err := n.Candidates(1)
344		if err != nil {
345			t.Fatal(err)
346		}
347		emptyFinal := candidateByID(t, final, emptyID)
348		if fmt.Sprint(pubHexList(emptyFinal.Voters)) != fmt.Sprint(sortedPubHex(keys[1].pub)) {
349			t.Fatalf("empty candidate voters = %x, want exactly keys[1]", emptyFinal.Voters)
350		}
351		if len(emptyFinal.TxIDs) != 0 {
352			t.Fatalf("empty candidate gained txs: %v", emptyFinal.TxIDs)
353		}
354	}
