81		}
82		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub, keys[0].pub}, MaxTxsPerBlock: 1}); err == nil {
83			t.Fatal("duplicate validators should be rejected")
84		}
