247	// 打包顺序：跨账户按费用，同账户后续序号必须等前一条被选入；达到上限停止。
248	func TestPackingOrder(t *testing.T) {
249		keys := genKeys(t, 4)
250		n, _ := newTestNode(t, keys, 2)
251	
252		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
253		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100) // 费用最高，但必须等 a1 选入后才可考虑
254		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
255		for _, tx := range []*Transaction{a1, a2, b1} {
256			if _, err := n.Submit(tx); err != nil {
257				t.Fatal(err)
258			}
259		}
260		p, err := n.Propose()
261		if err != nil {
262			t.Fatal(err)
263		}
264		// 第一次取各账户下一条：b1(50) 高于 a1(10)；第二次只有 a1 可确认，
265		// a2 因序号缺口本轮取不到，且已达上限 2。
266		want := []string{b1.ID(), a1.ID()}
267		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
268			t.Fatalf("packed %v, want %v", p.TxIDs, want)
269		}
270		// 确认后下一轮 a2 成为该账户下一条可确认交易并被打包
271		confirmByVotes(t, n, keys, p.BlockID)
272		p2, err := n.Propose()
273		if err != nil {
274			t.Fatal(err)
275		}
276		if len(p2.TxIDs) != 1 || p2.TxIDs[0] != a2.ID() {
277			t.Fatalf("round 2 packed %v, want [a2]", p2.TxIDs)
278		}
279	}
