1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// 本文件钉住竞争候选登记的账户序号规则回归保障：交易可以先进入池中等待，
9	// 候选却不能借用没有写进自己列表的前序交易；不同账户可以交错出现，同一账户
10	// 仍须按列表中的实际出现顺序，从该账户已确认序号加一开始连续递增。
11	//
12	// 场景：第 1 轮确认 a1、a2、b1，使三个账户的已确认序号分别为 2、1、0（互不
13	// 相同，且至少一个非零）。第 2 轮本地提议已产生且尚未确认，按费用打包
14	// [a3, b2, c1, a4]；b3、c2 在提议冻结后才提交，仅在池中排队。既有竞争候选
15	// alt1=[c1, c2] 持有一张未达门槛的票。随后登记的新候选列表 [b2, a3, c1, b3, a4]
16	// 与本地提议顺序不同：相邻交易来自不同账户，费用高低也不按本地打包顺序排列，
17	// 但每个账户自己的序号连续（A:3,4；B:2,3；C:1），按现有规则必须登记成功。
18	//
19	// 登记成功的公开效果是：新候选入册，按轮次查询保留调用者给出的完整交易顺序，
20	// 不按账户、序号或费用重排；本地提议保持原来的标识与顺序；登记不推进任何
21	// 账户的已确认序号、不产生确认块；新候选实际引用的排队交易 b3 才转为等待
22	// 投票，已有候选引用的交易（含 alt1 独有的 c2）继续保持等待投票。
23	//
24	// 拒绝路径区分两种容易误判的情况，都以 sequence-not-consecutive 拒绝：
25	//   - 某账户需要的前序交易虽在池中（甚至已被本地提议引用），但候选从更后的
26	//     序号开始或中途跳过它；
27	//   - 某账户的连续序号交易都在列表里，但后一个序号先于前一个出现，其他账户
28	//     夹在中间不能掩盖倒序。
29	// 这些列表都满足其他登记条件（不超单块上限、无未知或重复交易、均在池中），
30	// 不能让其他原因代替序号拒绝。拒绝后候选集合、本地提议与既有候选票数保持
31	// 原样；原本只在排队的交易仍等待打包、可加费替换，原本等待投票的交易仍被
32	// 锁定、不能被解锁。
33	//
34	// 本组测试不新增公开入口，也不改变现有登记、投票与交易规则。
35	
36	// seqScene 收拢“账户序号规则”场景的关键句柄。
37	type seqScene struct {
38		block1 Block
39		local  ProposalView
40		alt1ID string
41		// a3、a4、b2、c1 被本地提议引用：等待投票。
42		a3 *Transaction
43		a4 *Transaction
44		b2 *Transaction
45		c1 *Transaction
46		// b3 在本地提议冻结后才提交，仅排队；新候选首次引用它。
47		b3 *Transaction
48		// c2 仅被既有竞争候选 alt1 引用：等待投票。
49		c2 *Transaction
50		// list 是待登记的竞争候选列表，顺序与本地提议不同。
51		list []string
52	}
53	
54	// buildSeqScene 构造第 2 轮未决场景：确认历史使账户 A/B/C 的已确认序号为
55	// 2/1/0；本地提议 [a3, b2, c1, a4]；b3、c2 仅排队；alt1=[c2] 持一票。
56	func buildSeqScene(t *testing.T, n *Node, keys []testKey) seqScene {
57		t.Helper()
58		// 第 1 轮：确认 a1、a2、b1，推进已确认序号 A=2、B=1，C 保持 0。
59		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
60		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 10, 100)
61		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 10, 100)
62		for _, tx := range []*Transaction{a1, a2, b1} {
63			if _, err := n.Submit(tx); err != nil {
64				t.Fatalf("setup submit %q: %v", tx.Content, err)
65			}
66		}
67		p1, err := n.Propose()
68		if err != nil {
69			t.Fatal(err)
70		}
71		confirmByVotes(t, n, keys, p1.BlockID)
72		if n.CurrentRound() != 2 || n.Height() != 1 {
73			t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
74		}
75		block1, ok := n.LatestBlock()
76		if !ok || block1.Height != 1 {
77			t.Fatalf("setup: latest block = %+v ok=%v, want height 1", block1, ok)
78		}
79		for i, want := range []uint64{2, 1, 0} {
80			if got := n.Account(keys[i].pub).ConfirmedSequence; got != want {
81				t.Fatalf("setup: account %d confirmed sequence = %d, want %d", i, got, want)
82			}
83		}
84	
85		// 第 2 轮：a3、a4、b2、c1 在本地提议前提交，按费用被打包进提议。
86		a3 := NewTransaction(keys[0].priv, 3, []byte("a3"), 50, 100)
87		a4 := NewTransaction(keys[0].priv, 4, []byte("a4"), 10, 100)
88		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 40, 100)
89		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 20, 100)
90		for _, tx := range []*Transaction{a3, a4, b2, c1} {
91			if _, err := n.Submit(tx); err != nil {
92				t.Fatalf("setup submit %q: %v", tx.Content, err)
93			}
94		}
95		local, err := n.Propose()
96		if err != nil {
97			t.Fatal(err)
98		}
99		wantLocal := []string{a3.ID(), b2.ID(), c1.ID(), a4.ID()}
100		if fmt.Sprint(local.TxIDs) != fmt.Sprint(wantLocal) {
101			t.Fatalf("setup: local proposal = %v, want %v", local.TxIDs, wantLocal)
102		}
103	
104		// 提议冻结后才提交的交易仅在池中排队，不被本地提议引用。
105		b3 := NewTransaction(keys[1].priv, 3, []byte("b3"), 30, 100)
106		c2 := NewTransaction(keys[2].priv, 2, []byte("c2"), 15, 100)
107		for _, tx := range []*Transaction{b3, c2} {
108			if _, err := n.Submit(tx); err != nil {
109				t.Fatalf("setup submit %q: %v", tx.Content, err)
110			}
111			if info := n.mustTx(t, tx.ID()); info.Status != StatusQueued {
112				t.Fatalf("setup: %q status = %s, want queued", tx.Content, info.Status)
113			}
114		}
115	
116		// 既有竞争候选引用本地提议的 c1 与排队交易 c2（C 的序号自 1 起连续），
117		// 并持有一张未达门槛的票；c2 由此只被既有候选引用。
118		alt1, err := n.RegisterCandidate(2, []string{c1.ID(), c2.ID()})
119		if err != nil {
120			t.Fatal(err)
121		}
122		if alt1.Existing || alt1.BlockID == local.BlockID {
123			t.Fatalf("setup: alt1 must be a fresh candidate: %+v local=%s", alt1, local.BlockID)
124		}
125		if res, err := n.Vote(keys[0].pub, 2, alt1.BlockID); err != nil || !res.Counted || res.Confirmed {
126			t.Fatalf("setup vote for alt1: %+v %v", res, err)
127		}
128	
129		// 新候选列表：相邻交易来自不同账户，费用不按本地打包顺序排列，
130		// 但每个账户自己的序号从已确认序号加一起连续。
131		list := []string{b2.ID(), a3.ID(), c1.ID(), b3.ID(), a4.ID()}
132		return seqScene{
133			block1: block1,
134			local:  local,
135			alt1ID: alt1.BlockID,
136			a3:     a3,
137			a4:     a4,
138			b2:     b2,
139			c1:     c1,
140			b3:     b3,
141			c2:     c2,
142			list:   list,
143		}
144	}
145	
146	// assertSeqRoundStable 断言失败登记后必须保持不变的轮次状态：轮次 2、确认
147	// 高度 1；本地提议标识与顺序不变；候选集合仍只有本地提议与 alt1，alt1 保留
148	// 原票，未投票名单不变。
149	func assertSeqRoundStable(t *testing.T, n *Node, sc seqScene, keys []testKey) {
150		t.Helper()
151		if n.CurrentRound() != 2 || n.Height() != 1 {
152			t.Fatalf("round=%d height=%d, want 2/1 (rejected registers must not advance anything)",
153				n.CurrentRound(), n.Height())
154		}
155		latest, ok := n.LatestBlock()
156		if !ok || latest.ID != sc.block1.ID {
157			t.Fatalf("latest block = %+v ok=%v, want %s", latest, ok, sc.block1.ID)
158		}
159		p, ok := n.Proposal()
160		if !ok || p.BlockID != sc.local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(sc.local.TxIDs) {
161			t.Fatalf("local proposal changed: %+v ok=%v, want %+v", p, ok, sc.local)
162		}
163	
164		rc, err := n.Candidates(2)
165		if err != nil {
166			t.Fatal(err)
167		}
168		if rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords || len(rc.Candidates) != 2 {
169			t.Fatalf("round 2 must keep exactly the two original pending candidates: %+v", rc)
170		}
171		wantUnvoted := [][]byte{keys[1].pub, keys[2].pub, keys[3].pub}
172		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(wantUnvoted)) {
173			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, wantUnvoted)
174		}
175		var gotLocal, gotAlt *CandidateView
176		for i := range rc.Candidates {
177			switch rc.Candidates[i].BlockID {
178			case sc.local.BlockID:
179				gotLocal = &rc.Candidates[i]
180			case sc.alt1ID:
181				gotAlt = &rc.Candidates[i]
182			}
183		}
184		if gotLocal == nil || gotAlt == nil {
185			t.Fatalf("only the original candidates may remain: %+v", rc.Candidates)
186		}
187		if !gotLocal.Local || gotLocal.Result != CandidatePending ||
188			fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(sc.local.TxIDs) || len(gotLocal.Voters) != 0 {
189			t.Fatalf("local candidate changed: %+v", gotLocal)
190		}
191		if gotAlt.Local || gotAlt.Result != CandidatePending ||
192			fmt.Sprint(gotAlt.TxIDs) != fmt.Sprint([]string{sc.c1.ID(), sc.c2.ID()}) ||
193			len(gotAlt.Voters) != 1 || fmt.Sprintf("%x", gotAlt.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
194			t.Fatalf("existing competitor or its vote changed: %+v", gotAlt)
195		}
196	}
197	
198	// TestRegisterCandidateInterleavedSequences 钉住接受路径：当前轮次已有本地
199	// 提议且尚未确认时，调用者可以登记与本地提议顺序不同的交易列表——各账户
200	// 已确认序号不同（2/1/0，至少一个非零），相邻交易来自不同账户、费用不按
201	// 本地打包顺序排列，只要各账户自己的序号连续就必须成功；查询保留调用者
202	// 给出的完整顺序，本地提议冻结，登记不推进序号也不产生确认块，只有新候选
203	// 实际引用的排队交易才转为等待投票。
204	func TestRegisterCandidateInterleavedSequences(t *testing.T) {
205		keys := genKeys(t, 4)
206		n, _ := newTestNode(t, keys, 5)
207		sc := buildSeqScene(t, n, keys)
208	
209		// 候选接在最新确认块之后：轮次 2、高度 2、前块为第 1 轮确认块。
210		wantID := BlockID(2, 2, sc.block1.ID, sc.list)
211		if wantID == sc.local.BlockID || wantID == sc.alt1ID {
212			t.Fatal("setup: new candidate id must differ from both existing candidates")
213		}
214		res, err := n.RegisterCandidate(2, sc.list)
215		if err != nil {
216			t.Fatalf("interleaved candidate with per-account consecutive sequences must register: %v", err)
217		}
218		if res.Existing {
219			t.Fatal("the new list must register as a fresh candidate, not an existing one")
220		}
221		if res.BlockID != wantID {
222			t.Fatalf("block id = %s, want %s (round 2, height 2, prev %s, caller order)",
223				res.BlockID, wantID, sc.block1.ID)
224		}
225	
226		// 登记不推进轮次与确认高度，也不产生确认块。
227		if n.CurrentRound() != 2 || n.Height() != 1 {
228			t.Fatalf("round=%d height=%d, want 2/1 (register must not confirm)", n.CurrentRound(), n.Height())
229		}
230		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
231			t.Fatalf("block at height 2: %v, want %s", err, ReasonUnknownBlock)
232		}
233		latest, ok := n.LatestBlock()
234		if !ok || latest.ID != sc.block1.ID {
235			t.Fatalf("latest block changed: %+v ok=%v, want %s", latest, ok, sc.block1.ID)
236		}
237	
238		// 本地提议保持原来的标识与顺序。
239		p, ok := n.Proposal()
240		if !ok || p.BlockID != sc.local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(sc.local.TxIDs) {
241			t.Fatalf("local proposal changed: %+v ok=%v, want %+v", p, ok, sc.local)
242		}
243	
244		// 按轮次查询：新候选保留调用者给出的完整交易顺序，不按账户、序号或
245		// 费用重排；本地提议与既有候选及其票数不变。
246		rc, err := n.Candidates(2)
247		if err != nil {
248			t.Fatal(err)
249		}
250		if rc.Ended || !rc.HasRecords || len(rc.Candidates) != 3 {
251			t.Fatalf("round 2 must have exactly three pending candidates: %+v", rc)
252		}
253		var gotLocal, gotAlt, gotNew *CandidateView
254		for i := range rc.Candidates {
255			switch rc.Candidates[i].BlockID {
256			case sc.local.BlockID:
257				gotLocal = &rc.Candidates[i]
258			case sc.alt1ID:
259				gotAlt = &rc.Candidates[i]
260			case wantID:
261				gotNew = &rc.Candidates[i]
262			}
263		}
264		if gotLocal == nil || gotAlt == nil || gotNew == nil {
265			t.Fatalf("all three candidates must be present: %+v", rc.Candidates)
266		}
267		if gotNew.Local || gotNew.Result != CandidatePending || len(gotNew.Voters) != 0 {
268			t.Fatalf("new candidate must be a non-local pending candidate with no votes: %+v", gotNew)
269		}
270		if fmt.Sprint(gotNew.TxIDs) != fmt.Sprint(sc.list) {
271			t.Fatalf("candidate tx order = %v, want the exact caller order %v", gotNew.TxIDs, sc.list)
272		}
273		if !gotLocal.Local || fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(sc.local.TxIDs) || len(gotLocal.Voters) != 0 {
274			t.Fatalf("local candidate changed: %+v", gotLocal)
275		}
276		if len(gotAlt.Voters) != 1 || fmt.Sprintf("%x", gotAlt.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
277			t.Fatalf("existing competitor lost its vote: %+v", gotAlt)
278		}
279	
280		// 登记不推进任何账户的已确认序号；新候选实际引用的排队交易 b3 才转为
281		// 等待投票，已有候选引用的交易（含 alt1 独有的 c2）继续保持等待投票。
282		assertAccountQueue(t, n, keys[0].pub, 2, map[string]string{
283			sc.a3.ID(): "waiting-vote", sc.a4.ID(): "waiting-vote",
284		})
285		assertAccountQueue(t, n, keys[1].pub, 1, map[string]string{
286			sc.b2.ID(): "waiting-vote", sc.b3.ID(): "waiting-vote",
287		})
288		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
289			sc.c1.ID(): "waiting-vote", sc.c2.ID(): "waiting-vote",
290		})
291		if info := n.mustTx(t, sc.b3.ID()); info.Status != StatusProposed {
292			t.Fatalf("newly referenced b3 status = %s, want proposed", info.Status)
293		}
294		if info := n.mustTx(t, sc.c2.ID()); info.Status != StatusProposed {
295			t.Fatalf("c2 referenced by the earlier candidate must stay proposed, got %s", info.Status)
296		}
297	}
298	
299	// TestRegisterCandidateSequenceGapRejections 钉住拒绝路径：前序交易在池中
300	// （甚至已被本地提议引用）但候选跳过它，或同一账户的连续序号在列表中倒序
301	// 出现，都必须以 sequence-not-consecutive 拒绝；这些列表满足其他登记条件，
302	// 拒绝后候选集合、本地提议、既有候选票数与两类交易的状态全部保持原样。
303	func TestRegisterCandidateSequenceGapRejections(t *testing.T) {
304		keys := genKeys(t, 4)
305		n, _ := newTestNode(t, keys, 5)
306		sc := buildSeqScene(t, n, keys)
307	
308		// 额外的排队交易：a5 的前序 a4 已被本地提议引用，b4 的前序 b3 仅在池中排队。
309		a5 := NewTransaction(keys[0].priv, 5, []byte("a5"), 5, 100)
310		b4 := NewTransaction(keys[1].priv, 4, []byte("b4"), 5, 100)
311		for _, tx := range []*Transaction{a5, b4} {
312			if _, err := n.Submit(tx); err != nil {
313				t.Fatalf("setup submit %q: %v", tx.Content, err)
314			}
315		}
316	
317		cases := []struct {
318			name string
319			list []string
320		}{
321			// 前序交易 a3 在池中且已被本地提议引用，候选却从更后的序号 4 开始。
322			{"start beyond needed predecessor", []string{sc.a4.ID()}},
323			// 前序交易 a4 在池中且已被本地提议引用，候选中途跳过它。
324			{"skip proposed predecessor mid-list", []string{sc.a3.ID(), a5.ID()}},
325			// 前序交易 b3 仍在池中排队，候选中途跳过它。
326			{"skip queued predecessor mid-list", []string{sc.b2.ID(), b4.ID()}},
327			// A 的连续序号都在列表里，但 4 先于 3 出现；B、C 夹在中间不能掩盖倒序。
328			{"reversed order within one account", []string{sc.b2.ID(), sc.a4.ID(), sc.c1.ID(), sc.a3.ID()}},
329		}
330		for _, tc := range cases {
331			// 列表均不超单块上限、无未知或重复交易、全部在池中：
332			// 拒绝原因必须是序号不连续，而不是其他登记条件。
333			if _, err := n.RegisterCandidate(2, tc.list); reason(err) != ReasonSequenceGap {
334				t.Fatalf("%s: got %v, want %s", tc.name, err, ReasonSequenceGap)
335			}
336		}
337	
338		// 全部拒绝后：候选集合、本地提议与既有候选票数保持原样。
339		assertSeqRoundStable(t, n, sc, keys)
340	
341		// 原本只在排队的交易仍显示等待打包，不因失败登记被锁定；
342		// 原本等待投票的交易也不能被解锁；已确认序号不推进。
343		assertAccountQueue(t, n, keys[0].pub, 2, map[string]string{
344			sc.a3.ID(): "waiting-vote", sc.a4.ID(): "waiting-vote", a5.ID(): "waiting-pack",
345		})
346		assertAccountQueue(t, n, keys[1].pub, 1, map[string]string{
347			sc.b2.ID(): "waiting-vote", sc.b3.ID(): "waiting-pack", b4.ID(): "waiting-pack",
348		})
349		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{
350			sc.c1.ID(): "waiting-vote", sc.c2.ID(): "waiting-vote",
351		})
352		for _, tx := range []*Transaction{sc.b3, a5, b4} {
353			if info := n.mustTx(t, tx.ID()); info.Status != StatusQueued {
354				t.Fatalf("queued-only tx %q status = %s, want queued after rejected registers", tx.Content, info.Status)
355			}
356		}
357		for _, tx := range []*Transaction{sc.a3, sc.a4, sc.b2, sc.c1, sc.c2} {
358			if info := n.mustTx(t, tx.ID()); info.Status != StatusProposed {
359				t.Fatalf("referenced tx %q status = %s, want proposed after rejected registers", tx.Content, info.Status)
360			}
361		}
362	
363		// 排队交易 b3 没有被失败登记锁定：同发送者同序号、费用严格更高仍可替换。
364		b3hi := NewTransaction(keys[1].priv, 3, []byte("b3-hi"), 99, 100)
365		rep, err := n.Submit(b3hi)
366		if err != nil {
367			t.Fatalf("queued-only b3 must stay replaceable after rejected registers: %v", err)
368		}
369		if rep.ReplacedID != sc.b3.ID() {
370			t.Fatalf("replacement result = %+v, want ReplacedID %s", rep, sc.b3.ID())
371		}
372		if info := n.mustTx(t, sc.b3.ID()); info.Status != StatusReplaced || info.ReplacedBy != b3hi.ID() {
373			t.Fatalf("b3 after replacement = %+v, want replaced by %s", info, b3hi.ID())
374		}
375		// 已被候选引用的 a3 继续锁定：加费替换仍以 tx-in-proposal 拒绝。
376		a3hi := NewTransaction(keys[0].priv, 3, []byte("a3-hi"), 99, 100)
377		if _, err := n.Submit(a3hi); reason(err) != ReasonProposalLocked {
378			t.Fatalf("referenced a3 must stay locked, got %v, want %s", err, ReasonProposalLocked)
