12	// 候选登记的各类失败原因，失败时节点状态不变。
13	func TestRegisterCandidateValidation(t *testing.T) {
14		keys := genKeys(t, 4)
15		n, _ := newTestNode(t, keys, 2)
16	
17		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
18		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 1, 100)
19		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
20		for _, tx := range []*Transaction{a1, a2, b1} {
21			if _, err := n.Submit(tx); err != nil {
22				t.Fatal(err)
23			}
24		}
25	
26		// 尚未产生本地提议。
27		if _, err := n.RegisterCandidate(1, []string{a1.ID()}); reason(err) != ReasonNoProposal {
28			t.Fatalf("got %v, want %s", err, ReasonNoProposal)
29		}
30	
31		p, _ := n.Propose() // 上限 2：本地提议按费用选出 a1(10)、b1(5)，a2 因缺口留在池中。
32	
33		// 非当前轮次（轮次优先于其他校验）。
34		if _, err := n.RegisterCandidate(2, []string{a1.ID()}); reason(err) != ReasonWrongRound {
35			t.Fatalf("got %v, want %s", err, ReasonWrongRound)
36		}
37		// 未知交易。
38		if _, err := n.RegisterCandidate(1, []string{"deadbeef"}); reason(err) != ReasonUnknownTx {
39			t.Fatalf("got %v, want %s", err, ReasonUnknownTx)
40		}
41		// 列表重复。
42		if _, err := n.RegisterCandidate(1, []string{a1.ID(), a1.ID()}); reason(err) != ReasonDuplicateInList {
43			t.Fatalf("got %v, want %s", err, ReasonDuplicateInList)
44		}
45		// 超过单块上限。
46		if _, err := n.RegisterCandidate(1, []string{a1.ID(), a2.ID(), b1.ID()}); reason(err) != ReasonTooManyTxs {
47			t.Fatalf("got %v, want %s", err, ReasonTooManyTxs)
48		}
49		// 序号不连续：a2 之前缺少该账户序号 1。
50		if _, err := n.RegisterCandidate(1, []string{a2.ID()}); reason(err) != ReasonSequenceGap {
51			t.Fatalf("got %v, want %s", err, ReasonSequenceGap)
52		}
53		// 序号不连续：跳号。
54		if _, err := n.RegisterCandidate(1, []string{a1.ID(), a2.ID(), b1.ID()}); reason(err) != ReasonTooManyTxs {
55			t.Fatalf("limit check must precede sequence check, got %v", err)
56		}
57	
58		// 所有失败登记后状态不变：仍只有本地提议一个候选，引用之外的交易仍排队。
59		rc, err := n.Candidates(1)
60		if err != nil {
61			t.Fatal(err)
62		}
63		if len(rc.Candidates) != 1 || rc.Candidates[0].BlockID != p.BlockID || !rc.Candidates[0].Local {
64			t.Fatalf("failed registrations changed candidates: %+v", rc.Candidates)
65		}
66		if info, _ := n.Tx(a2.ID()); info.Status != StatusQueued || info.Note != "" {
67			t.Fatalf("a2 should stay queued, got %+v", info)
68		}
69	
70		// 合法登记：账户间顺序由调用者决定，账户内序号连续即可。
71		if _, err := n.RegisterCandidate(1, []string{a1.ID(), b1.ID()}); err != nil {
72			t.Fatalf("valid candidate rejected: %v", err)
73		}
74		// 允许空块候选。
75		if _, err := n.RegisterCandidate(1, nil); err != nil {
76			t.Fatalf("empty candidate rejected: %v", err)
77		}
78	}
