111	// 相同交易列表重复登记返回同一候选并保留已有票数；登记其他候选不动本地提议。
112	func TestRegisterCandidateIdempotentAndLocalStable(t *testing.T) {
113		keys := genKeys(t, 4)
114		n, _ := newTestNode(t, keys, 10)
115	
116		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
117		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
118		n.Submit(a1)
119		n.Submit(b1)
120		p1, _ := n.Propose() // 打包顺序：b1 先、a1 后。
121	
122		list := []string{a1.ID(), b1.ID()} // 顺序与本地提议相反
123		r1, err := n.RegisterCandidate(1, list)
124		if err != nil {
125			t.Fatal(err)
126		}
127		if r1.Existing || r1.BlockID == p1.BlockID {
128			t.Fatalf("new candidate wrong: %+v local=%s", r1, p1.BlockID)
129		}
130		// 预期区块标识可用同一编码复算。
131		wantID := BlockID(1, 1, "", list)
132		if r1.BlockID != wantID {
133			t.Fatalf("block id %s != recomputed %s", r1.BlockID, wantID)
134		}
135	
136		// 投一票给竞争候选，再用相同列表重复登记。
137		if _, err := n.Vote(keys[0].pub, 1, r1.BlockID); err != nil {
138			t.Fatal(err)
139		}
140		r2, err := n.RegisterCandidate(1, append([]string{}, list...))
141		if err != nil {
142			t.Fatal(err)
143		}
144		if !r2.Existing || r2.BlockID != r1.BlockID {
145			t.Fatalf("same list should return same candidate: %+v vs %+v", r1, r2)
146		}
147		rc, _ := n.Candidates(1)
148		var alt *CandidateView
149		for i := range rc.Candidates {
150			if rc.Candidates[i].BlockID == r1.BlockID {
151				alt = &rc.Candidates[i]
152			}
153		}
154		if alt == nil || len(alt.Voters) != 1 {
155			t.Fatalf("votes not preserved on duplicate register: %+v", alt)
156		}
157	
158		// Propose/Proposal 始终返回不变的本地提议。
159		p2, err := n.Propose()
160		if err != nil {
161			t.Fatal(err)
162		}
163		p3, ok := n.Proposal()
164		if !ok || p2.BlockID != p1.BlockID || p3.BlockID != p1.BlockID {
165			t.Fatalf("local proposal changed: %s %s %s", p1.BlockID, p2.BlockID, p3.BlockID)
166		}
167		if fmt.Sprint(p3.TxIDs) != fmt.Sprint(p1.TxIDs) {
168			t.Fatal("local proposal tx order changed")
169		}
170	}
