182		if len(local.TxIDs) != 1 || local.TxIDs[0] != a1.ID() {
183			t.Fatalf("setup: local should only contain a1, got %v", local.TxIDs)
184		}
185	
186		// b1 仅在竞争候选中出现。
187		alt, err := n.RegisterCandidate(1, []string{b1.ID()})
188		if err != nil {
189			t.Fatal(err)
190		}
191		info, _ := n.Tx(b1.ID())
192		if info.Status != StatusProposed {
193			t.Fatalf("alt-candidate tx status = %s, want proposed", info.Status)
194		}
195		acct := n.Account(keys[1].pub)
196		if len(acct.Pending) != 1 || acct.Pending[0].Note != "waiting-vote" {
197			t.Fatalf("alt-candidate tx note = %+v, want waiting-vote", acct.Pending)
198		}
199		replace := NewTransaction(keys[1].priv, 1, []byte("b1hi"), 99, 100)
200		if _, err := n.Submit(replace); reason(err) != ReasonProposalLocked {
201			t.Fatalf("replacing alt-candidate tx got %v, want %s", err, ReasonProposalLocked)
202		}
203	
204		// 仅在池中等待（未被任何候选引用）的交易仍可替换。
205		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 1, 100)
206		n.Submit(c1)
207		c1hi := NewTransaction(keys[2].priv, 1, []byte("c1hi"), 2, 100)
208		if _, err := n.Submit(c1hi); err != nil {
209			t.Fatalf("queued-only tx should remain replaceable: %v", err)
210		}
211		_ = alt
