695		}
696		b, err := n2.BlockAt(1)
697		if err != nil || b.ID != block1.ID {
698			t.Fatalf("confirmed block not preserved: %+v %v", b, err)
699		}
700		rc1, err := n2.Candidates(1)
701		if err != nil {
702			t.Fatal(err)
703		}
704		if rc1.HasRecords || !rc1.Ended || rc1.UnconfirmedEnd || len(rc1.Candidates) != 0 {
705			t.Fatalf("v1 confirmed round should show no records: %+v", rc1)
706		}
707		rc2, err := n2.Candidates(2)
708		if err != nil {
709			t.Fatal(err)
710		}
711		if rc2.HasRecords || !rc2.Ended || !rc2.UnconfirmedEnd {
712			t.Fatalf("v1 ended round should show unconfirmed-end with no records: %+v", rc2)
713		}
714		// 当前轮次尚未提议，查询按未知轮次处理。
715		if _, err := n2.Candidates(3); reason(err) != ReasonUnknownRound {
716			t.Fatalf("current round without proposal got %v, want %s", err, ReasonUnknownRound)
717		}
718		// 迁移后的节点可以继续正常工作。
719		p3, err := n2.Propose()
720		if err != nil || p3.Round != 3 {
721			t.Fatalf("propose after v1 migration: %+v %v", p3, err)
722		}
723	}
